package com.orderflow.delivery.service;
import com.orderflow.delivery.domain.*;import com.orderflow.delivery.error.DeliveryDomainException;import com.orderflow.delivery.repository.*;import com.orderflow.platform.error.ErrorCode;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DeliveryAssignmentService{private final DeliveryRepository deliveries;private final DeliveryAgentRepository agents;private final DeliveryStatusHistoryRepository history;private final DeliveryEventOutbox events;private final MeterRegistry metrics;private final Clock clock;public DeliveryAssignmentService(DeliveryRepository d,DeliveryAgentRepository a,DeliveryStatusHistoryRepository h,DeliveryEventOutbox e,MeterRegistry m,Clock c){deliveries=d;agents=a;history=h;events=e;metrics=m;clock=c;}
 @Transactional public boolean autoAssign(UUID deliveryId,String correlation,UUID cause){Delivery d=deliveries.lockById(deliveryId).orElseThrow();if(d.getStatus()!=DeliveryStatus.PENDING_ASSIGNMENT)return false;var a=agents.lockNextAvailable().orElse(null);if(a==null)return false;assign(d,a,correlation,cause);return true;}
 @Transactional public void manualAssign(UUID deliveryId,UUID agentId,String correlation){Delivery d=deliveries.lockById(deliveryId).orElseThrow(()->error(ErrorCode.DELIVERY_NOT_FOUND,"Delivery not found"));DeliveryAgentProfile a=agents.lockById(agentId).orElseThrow(()->error(ErrorCode.DELIVERY_AGENT_NOT_FOUND,"Delivery agent not found"));if(d.getStatus()!=DeliveryStatus.PENDING_ASSIGNMENT)throw error(ErrorCode.DELIVERY_ALREADY_ASSIGNED,"Delivery is not pending assignment");if(a.getAvailability()!=DeliveryAgentAvailability.AVAILABLE)throw error(ErrorCode.DELIVERY_AGENT_NOT_AVAILABLE,"Delivery agent is not available");assign(d,a,correlation,null);}
 @Transactional public DeliveryAgentProfile availability(UUID userId,DeliveryAgentAvailability next,String correlation){Instant now=Instant.now(clock);DeliveryAgentProfile a=agents.lockByUserId(userId).orElseGet(()->agents.saveAndFlush(DeliveryAgentProfile.register(userId,now)));try{a.setUserAvailability(next,now);}catch(IllegalArgumentException|IllegalStateException e){throw error(ErrorCode.DELIVERY_AGENT_BUSY,e.getMessage());}if(next==DeliveryAgentAvailability.AVAILABLE){Delivery d=deliveries.lockOldestPending().orElse(null);if(d!=null)assign(d,a,correlation,null);}return a;}
 private void assign(Delivery d,DeliveryAgentProfile a,String correlation,UUID cause){Instant now=Instant.now(clock);DeliveryStatus previous=d.getStatus();d.assign(a.getId(),now);a.assigned(now);history.save(new DeliveryStatusHistory(d.getId(),previous,d.getStatus(),a.getUserId(),cause,correlation,now));events.assigned(d,correlation,cause,now);metrics.counter("delivery_assignments_total","result","success").increment();}
 private DeliveryDomainException error(ErrorCode c,String m){return new DeliveryDomainException(HttpStatus.CONFLICT,c,m);}
}
